import { useState } from "react";
import useHttp from "./use_http";
import moment from "moment";

const useCdr = () => {
  const { httpService } = useHttp();
  const [cdrLoadings, setCdrLoadings] = useState({
    getCdrs: false,
    getCdrsExport: false,
  });
  const [cdrPaginates, setCdrPaginates] = useState({
    current: 1,
    total: 1,
    per_page: 10,
  });

  const [filters, setFilters] = useState({
    session_id: "",
    origin_host: "",
    used_balance: "",
    category: null,
    account: "",
    cc_request_type: null,
    calling_party: "",
    called_party: "",
    start: null,
    end: null,
  });

  const [cdrList, setCdrList] = useState([]);

  const getCdrs = async (page, filtersData) => {
    const paramsData = {
      page: page,
    };
    if (filtersData.session_id.length > 0) {
      paramsData["session_id"] = filtersData.session_id;
    }
    if (filtersData.origin_host.length > 0) {
      paramsData["origin_host"] = filtersData.origin_host;
    }
    if (filtersData.used_balance.length > 0) {
      paramsData["used_balance"] = filtersData.used_balance;
    }
    if (filtersData.category) {
      paramsData["category"] = filtersData?.category?.value;
    }
    if (filtersData.account.length > 0) {
      paramsData["account"] = filtersData.account;
    }
    if (filtersData.cc_request_type) {
      paramsData["cc_request_type"] = filtersData?.cc_request_type?.value;
    }
    if (filtersData.calling_party.length > 0) {
      paramsData["calling_party"] = filtersData.calling_party;
    }
    if (filtersData.called_party.length > 0) {
      paramsData["called_party"] = filtersData.called_party;
    }
    if (filtersData.start) {
      paramsData[
        "time_gt"
      ] = `${filtersData?.start?.year}-${filtersData?.start?.month}-${filtersData?.start?.day}T00:00:00Z`;
    }
    if (filtersData.end) {
      paramsData[
        "time_lt"
      ] = `${filtersData?.end?.year}-${filtersData?.end?.month}-${filtersData?.end?.day}T23:59:59Z`;
    }

    try {
      setCdrLoadings({ ...cdrLoadings, getCdrs: true });
      const response = await httpService.get(`/v1/cdrs`, {
        params: paramsData,
      });
      setCdrLoadings({ ...cdrLoadings, getCdrs: false });
      setCdrPaginates({
        ...cdrPaginates,
        current: response.data.meta.page,
        total: response.data.meta.pages,
        per_page: response.data.meta.limit,
      });
      if (response.data.data) {
        setCdrList(response.data.data);
      } else {
        setCdrList([]);
      }
    } catch ({ err, response }) {
      setCdrLoadings({ ...cdrLoadings, getCdrs: false });
    }
  };

  const getCdrsExport = async (filtersData) => {
    const paramsData = {};
    if (filtersData.session_id.length > 0) {
      paramsData["session_id"] = filtersData.session_id;
    }
    if (filtersData.origin_host.length > 0) {
      paramsData["origin_host"] = filtersData.origin_host;
    }
    if (filtersData.used_balance.length > 0) {
      paramsData["used_balance"] = filtersData.used_balance;
    }
    if (filtersData.category) {
      paramsData["category"] = filtersData?.category?.value;
    }
    if (filtersData.account.length > 0) {
      paramsData["account"] = filtersData.account;
    }
    if (filtersData.cc_request_type) {
      paramsData["cc_request_type"] = filtersData?.cc_request_type?.value;
    }
    if (filtersData.calling_party.length > 0) {
      paramsData["calling_party"] = filtersData.calling_party;
    }
    if (filtersData.called_party.length > 0) {
      paramsData["called_party"] = filtersData.called_party;
    }
    if (filtersData.start) {
      paramsData[
        "time_gt"
      ] = `${filtersData?.start?.year}-${filtersData?.start?.month}-${filtersData?.start?.day}T00:00:00Z`;
    }
    if (filtersData.end) {
      paramsData[
        "time_lt"
      ] = `${filtersData?.end?.year}-${filtersData?.end?.month}-${filtersData?.end?.day}T23:59:59Z`;
    }

    try {
      setCdrLoadings({ ...cdrLoadings, getCdrsExport: true });
      const response = await httpService.get(`/v1/cdrs/export`, {
        params: paramsData,
      });
      setCdrLoadings({ ...cdrLoadings, getCdrsExport: false });
      // Create a blob from the response
      const blob = new Blob([response.data], { type: "text/csv" });

      // Create a download link
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;

      // Define the file name for download
      link.setAttribute(
        "download",
        `cdr_export_${moment().format("YYYY-MM-DD")}.csv`
      );

      // Append link to body, click it, and remove it
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch ({ err, response }) {
      setCdrLoadings({ ...cdrLoadings, getCdrsExport: false });
    }
  };

  const exports = {
    getCdrs,
    getCdrsExport,
    cdrList,
    filters,
    setFilters,
    cdrPaginates,
    setCdrPaginates,
    cdrLoadings,
  };
  return exports;
};
export default useCdr;
