import { Fragment, useEffect } from "react";
import Breadcrumbs from "@components/breadcrumbs";
import { useSkin } from "@hooks/useSkin";
import { ChevronDown } from "react-feather";
import { columns } from "./datatable/columns";
import DataTable from "react-data-table-component";
import ProgressLoading from "../../../components/progress_loading";
import {
  UncontrolledAccordion,
  AccordionItem,
  AccordionHeader,
  AccordionBody,
  Card,
  Row,
  Col,
  Label,
  Input,
  Button,
} from "reactstrap";
import Select from "react-select";
import { selectThemeColors } from "@utils";
import CustomDatePicker from "../../../components/datepicker";
import useCdr from "../../../hooks/use_cdr";
import ReactPaginate from "react-paginate";

const AllCDRs = () => {
  const { skin } = useSkin();
  const {
    getCdrs,
    getCdrsExport,
    cdrList,
    filters,
    setFilters,
    cdrPaginates,
    setCdrPaginates,
    cdrLoadings,
  } = useCdr();

  const handlePagination = (page) => {
    setCdrPaginates({ ...cdrPaginates, current: page.selected });
    getCdrs(page.selected + 1, filters);
  };

  // ** Custom Pagination
  const CustomPagination = () => (
    <div className="d-flex align-items-center flex-row-reverse justify-content-between">
      <ReactPaginate
        previousLabel=""
        nextLabel=""
        forcePage={cdrPaginates.current - 1}
        onPageChange={(page) => handlePagination(page)}
        pageCount={cdrPaginates.total}
        breakLabel="..."
        pageRangeDisplayed={2}
        marginPagesDisplayed={2}
        activeClassName="active"
        pageClassName="page-item"
        breakClassName="page-item"
        nextLinkClassName="page-link"
        pageLinkClassName="page-link"
        breakLinkClassName="page-link"
        previousLinkClassName="page-link"
        nextClassName="page-item next-item"
        previousClassName="page-item prev-item"
        containerClassName="pagination react-paginate separated-pagination pagination-sm justify-content-end pe-1 mt-1"
      />
      <Button
        onClick={() => getCdrsExport(filters)}
        disabled={cdrLoadings.getCdrsExport}
        color="success"
      >
        {cdrLoadings.getCdrsExport ? "Downloading..." : "Export Data"}
      </Button>
    </div>
  );

  useEffect(() => {
    setCdrPaginates({ ...cdrPaginates, current: 1 });
    getCdrs(1, filters);
  }, []);

  return (
    <Fragment>
      <Breadcrumbs
        title="CDRs List"
        data={[{ title: "CDRs" }, { title: "CDRs List" }]}
      />
      {/* filterbar */}
      <Card>
        <UncontrolledAccordion>
          <AccordionItem>
            <AccordionHeader targetId="1">Filters</AccordionHeader>
            <AccordionBody accordionId="1">
              <Row>
                {/* session_id */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="session_id">session_id</Label>
                  <Input
                    value={filters.session_id}
                    onChange={(e) =>
                      setFilters({ ...filters, session_id: e.target.value })
                    }
                    name="session_id"
                    id="session_id"
                  />
                </Col>
                {/* origin_host */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="origin_host">origin_host</Label>
                  <Input
                    value={filters.origin_host}
                    onChange={(e) =>
                      setFilters({ ...filters, origin_host: e.target.value })
                    }
                    name="origin_host"
                    id="origin_host"
                  />
                </Col>
                {/* used_balance */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="used_balance">used_balance</Label>
                  <Input
                    value={filters.used_balance}
                    onChange={(e) =>
                      setFilters({ ...filters, used_balance: e.target.value })
                    }
                    name="used_balance"
                    id="used_balance"
                  />
                </Col>
                {/* category */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="category">category</Label>
                  <Select
                    isClearable={false}
                    theme={selectThemeColors}
                    closeMenuOnSelect={true}
                    placeholder="select option"
                    maxMenuHeight={120}
                    options={[
                      { label: "video", value: "video" },
                      { label: "voice", value: "voice" },
                      { label: "data", value: "data" },
                    ]}
                    className={`react-select`}
                    classNamePrefix="select"
                    id="category"
                    name="category"
                    value={filters.category}
                    onChange={(value) =>
                      setFilters({ ...filters, category: value })
                    }
                  />
                </Col>
                {/* account */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="account">account</Label>
                  <Input
                    value={filters.account}
                    onChange={(e) =>
                      setFilters({ ...filters, account: e.target.value })
                    }
                    name="account"
                    id="account"
                  />
                </Col>
                {/* cc_request_type */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="cc_request_type">cc_request_type</Label>
                  <Select
                    isClearable={false}
                    theme={selectThemeColors}
                    closeMenuOnSelect={true}
                    placeholder="select option"
                    maxMenuHeight={120}
                    options={[
                      { label: "initial", value: "initial" },
                      { label: "update", value: "update" },
                      { label: "terminate", value: "terminate" },
                    ]}
                    className={`react-select`}
                    classNamePrefix="select"
                    id="cc_request_type"
                    name="cc_request_type"
                    value={filters.cc_request_type}
                    onChange={(value) =>
                      setFilters({ ...filters, cc_request_type: value })
                    }
                  />
                </Col>
                {/* calling_party */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="calling_party">calling_party</Label>
                  <Input
                    value={filters.calling_party}
                    onChange={(e) =>
                      setFilters({ ...filters, calling_party: e.target.value })
                    }
                    name="calling_party"
                    id="calling_party"
                  />
                </Col>
                {/* called_party */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="called_party">called_party</Label>
                  <Input
                    value={filters.called_party}
                    onChange={(e) =>
                      setFilters({ ...filters, called_party: e.target.value })
                    }
                    name="called_party"
                    id="called_party"
                  />
                </Col>
                {/* start */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="start">start</Label>
                  <CustomDatePicker
                    value={filters.start}
                    onChange={(value) =>
                      setFilters({ ...filters, start: value })
                    }
                    inputPlaceholder="select date"
                    calendarPopperPosition={"top"}
                  />
                </Col>
                {/* end */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="end">end</Label>
                  <CustomDatePicker
                    value={filters.end}
                    onChange={(value) => setFilters({ ...filters, end: value })}
                    inputPlaceholder="select date"
                    calendarPopperPosition={"top"}
                  />
                </Col>
                {/* actions */}
                <Col xs="12" className={"d-flex justify-content-end"}>
                  <Button
                    style={{ marginRight: 8 }}
                    color="danger"
                    onClick={() => {
                      setCdrPaginates({ ...cdrPaginates, current: 1 });
                      getCdrs(1, {
                        session_id: "",
                        origin_host: "",
                        used_balance: "",
                        category: null,
                        account: "",
                        cc_request_type: null,
                        calling_party: "",
                        called_party: "",
                        start: null,
                        end: null,
                      });
                      setFilters({
                        session_id: "",
                        origin_host: "",
                        used_balance: "",
                        category: null,
                        account: "",
                        cc_request_type: null,
                        calling_party: "",
                        called_party: "",
                        start: null,
                        end: null,
                      });
                    }}
                  >
                    Clear
                  </Button>
                  <Button
                    onClick={() => {
                      setCdrPaginates({ ...cdrPaginates, current: 1 });
                      getCdrs(1, filters);
                    }}
                    style={{ width: 150 }}
                    color="primary"
                  >
                    Filter
                  </Button>
                </Col>
              </Row>
            </AccordionBody>
          </AccordionItem>
        </UncontrolledAccordion>
      </Card>
      {/* datatable */}
      <div className="react-dataTable mv_datatable_container">
        <DataTable
          noDataComponent={
            cdrLoadings.getCdrs ? (
              ""
            ) : (
              <div style={{ margin: "24px 0" }}>No CDR Founded!</div>
            )
          }
          noHeader
          pagination
          columns={columns}
          paginationPerPage={cdrPaginates.per_page}
          className="react-dataTable"
          sortIcon={<ChevronDown size={10} />}
          paginationComponent={CustomPagination}
          data={cdrList}
          theme={skin === "dark" ? "darkTheme" : ""}
        />
        {cdrLoadings.getCdrs ? (
          <div className="datatable_loading_cover">
            <ProgressLoading />
          </div>
        ) : null}
      </div>
    </Fragment>
  );
};
export default AllCDRs;
